; =====================================================================
;  TILES.ASM -- generated by tools/mkfont.py; do not edit by hand
;  Map tile numbers and cell kinds.  Tile n = characters 2n, 2n+1.
; =====================================================================

T_SEA      = 0    ; open sea
T_GRASS    = 1    ; plain grass
T_FORT     = 2    ; 1 fort
T_FACTORY  = 3    ; 2 factory
T_CROP     = 4    ; 3 crop
T_SCHOOL   = 5    ; 4 school
T_HOSPITAL = 6    ; 5 hospital
T_HOUSE    = 7    ; 6 house
T_REBEL    = 8    ; 7 rebel
T_PTBOAT   = 9    ; 8 PT boat
T_FISHBOAT = 10   ; 9 fishing boat
T_WRECK    = 11   ; wreck of a parked boat
T_SPARE    = 12   ; spare (blank)
T_ROCK     = 13   ; rock (decorative)
T_ITEM     = 2    ; item k (1-9) is tile T_ITEM+k-1
N_TILES    = 32   ; number of tiles

; Cell kinds (ISLKIND); bit 7 set = square belongs to player 1
K_SEA      = $00  ; open sea
K_LAND     = $01  ; land, buildable
K_COAST    = $02  ; diagonal coast: not buildable, blocks boats
K_HARB     = $03  ; harbour: boats launch and park here
K_ROCK     = $04  ; rock: decorative, plays as sea
K_KIND     = $7F  ; mask for the kind
K_P1       = $80  ; owner bit: player 1 (right island)
